contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _from, address _to, uint256 _amount) public payable {
        // Setup: ensure _from has balance and has approved this contract for _amount.
        // We can only observe public state, but transferFrom requires allowance[msg.sender][_from].
        // We give _from a balance by transferring from this contract (which owns totalDistributed).
        // But this contract's balance may be zero. Instead, use the fact that c itself has an owner balance.
        // Since we only need a valid transferFrom, we can attempt it and check the allowance change on success.
        // To guarantee setup, we call approve on behalf of _from? No, approve sets msg.sender's allowance.
        // Our only way to set allowance[msg.sender][_from] is if _from == msg.sender, but we need a key for _from.
        // However, the property is about the caller's allowance for _from after transferFrom.
        // We can attempt transferFrom and capture whether it succeeds; the rule should hold when it succeeds.
        // To make it likely to succeed, we need _from to have approved this contract and have balance.
        // We cannot guarantee that from parameters alone. But we can try: if it reverts, the rule is vacuously true.
        // The checker will try to prove the assert for ALL inputs, so the rule must hold even on revert.
        // So we assert: (reverted) || (allowance[msg.sender][_from] == oldAllowance - _amount).
        // But we cannot read allowance[msg.sender][_from] before the call? We can call c.allowance(msg.sender, _from).
        uint256 oldAllowance = c.allowance(address(this), _from);
        bool reverted;
        try c.transferFrom(_from, _to, _amount) returns (bool success) {
            reverted = !success;
        } catch {
            reverted = true;
        }
        uint256 newAllowance = c.allowance(address(this), _from);
        // General rule: if the call succeeds (no revert and returns true), then allowance decreased exactly by _amount.
        assert(reverted || newAllowance == oldAllowance - _amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _from, address _to, uint256 _amount) public payable {
        require(_to != address(0));
        require(_from != address(0));
        require(_amount > 0);
        require(c.blacklist(_from) == false);
        require(c.totalRemaining() >= _amount);

        // Setup: give this contract a balance to transfer to _from, so that _from has tokens.
        // We must call getTokens to receive tokens, but that requires msg.sender not blacklisted.
        // We can call transferFrom directly only if _from approves this contract and has balance.
        // However, we cannot force _from to approve us. Instead, we use the fact that the contract
        // itself has a balance from the constructor (totalDistributed) and can transfer to _from.
        // So we first transfer tokens from this contract to _from.
        // But this contract's balance may be zero if totalDistributed was already spent.
        // We cannot guarantee _from's balance or approval. Thus the call may revert.
        // The rule is conditional on success.

        uint256 oldAllowance = c.allowance(address(this), _from);

        bool reverted;
        try c.transferFrom(_from, _to, _amount) returns (bool success) {
            reverted = !success;
        } catch {
            reverted = true;
        }

        uint256 newAllowance = c.allowance(address(this), _from);

        assert(reverted || newAllowance == oldAllowance - _amount);
    }

    receive() external payable {}
}

