    }

    function run(address _from, address _to, uint256 _amount) public {
        require(_to != address(0));
        require(_amount > 0);
        require(_amount <= c.allowance(_from, address(this)));

        uint256 oldAllowance = c.allowance(_from, address(this));

        bool reverted;
        try c.transferFrom(_from, _to, _amount) returns (bool success) {
            reverted = !success;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.allowance(_from, address(this)) == oldAllowance - _amount);
        } else {
            assert(c.allowance(_from, address(this)) == oldAllowance);
        }
    }

    receive() external payable {}
}

