    }

    function run(uint256 /*unused*/) public payable {
        // Ensure we are the owner so finishDistribution does not revert
        c.transferOwnership(address(this));

        bool firstReverted;
        try c.finishDistribution() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool firstResult = c.distributionFinished();

